-- Insert Bins (52 bins)
ON CONFLICT (id) DO UPDATE SET fill_percentage = EXCLUDED.fill_percentage, priority_score = EXCLUDED.priority_score, status = EXCLUDED.status;

-- Insert Vehicles (6 vehicles)
ON CONFLICT (id) DO NOTHING;

-- Insert Initial Alerts (12 alerts)
ON CONFLICT (id) DO NOTHING;

-- Insert Initial Predictions (52 predictions)
ON CONFLICT (id) DO NOTHING;

